namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = "";
    public string CourseNumber { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string InstructorName { get; set; } = "";
    public string InstructorBio { get; set; } = "";
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = "";
    public string StudentId { get; set; } = "";
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
        new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
        new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and human civilization." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She specializes in programming pedagogy and has published extensively on introductory CS curricula.", IsFeatured = true },
        new() { Id = 2, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres is an expert in algorithm design and competitive programming. He has coached multiple teams to success at the ACM ICPC.", IsFeatured = true },
        new() { Id = 3, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "350", Title = "Database Systems", Description = "Relational database design, SQL, normalization, transaction processing, and introduction to NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Lisa Park", InstructorBio = "Dr. Park spent a decade at a major database vendor before joining academia. Her research focuses on query optimization and distributed databases.", IsFeatured = false },
        new() { Id = 4, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. James Wilson", InstructorBio = "Dr. Wilson has been teaching calculus for over 20 years and is known for his engaging lecture style and commitment to student success.", IsFeatured = true },
        new() { Id = 5, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "210", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Ana Rodriguez", InstructorBio = "Dr. Rodriguez is an award-winning educator whose research bridges abstract algebra and applied machine learning.", IsFeatured = false },
        new() { Id = 6, DepartmentId = 3, DepartmentCode = "PHYS", CourseNumber = "101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Thu Lab 2:00–4:50 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an experimental physicist with expertise in condensed matter physics and a passion for hands-on learning.", IsFeatured = false },
        new() { Id = 7, DepartmentId = 3, DepartmentCode = "PHYS", CourseNumber = "220", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Emily Foster", InstructorBio = "Dr. Foster's research in photonics has been recognized with multiple national awards. She brings real-world applications into every lecture.", IsFeatured = true },
        new() { Id = 8, DepartmentId = 4, DepartmentCode = "ENG", CourseNumber = "101", Title = "Composition and Rhetoric", Description = "Develop college-level writing skills through essays, research papers, and peer review workshops.", Credits = 3, Schedule = "Mon/Wed 9:00–10:20 AM", InstructorName = "Prof. David Blake", InstructorBio = "Prof. Blake is a published novelist and essayist who brings creative energy to academic writing instruction.", IsFeatured = false },
        new() { Id = 9, DepartmentId = 4, DepartmentCode = "ENG", CourseNumber = "250", Title = "American Literature", Description = "Survey of major American literary works from the colonial period to the present day.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Maria Santos", InstructorBio = "Dr. Santos specializes in 20th-century American fiction and has published three books on the Harlem Renaissance.", IsFeatured = false },
        new() { Id = 10, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "101", Title = "World Civilizations", Description = "A broad survey of world history from ancient civilizations through the modern era, examining political, social, and cultural developments.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Thomas Grant", InstructorBio = "Dr. Grant is a historian of global trade networks and has conducted fieldwork on four continents.", IsFeatured = false },
        new() { Id = 11, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "310", Title = "The Renaissance", Description = "In-depth study of the cultural, artistic, and intellectual transformations of 14th–17th century Europe.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", InstructorName = "Dr. Catherine Moore", InstructorBio = "Dr. Moore is an art historian who has curated exhibitions at major museums and specializes in Italian Renaissance art.", IsFeatured = true },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseNumber.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.DepartmentCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && request.CourseId > 0;
    }
}

