arguments.file_text:
@page "/enroll"

<PageTitle>Enrollment Request</PageTitle>

@inject CourseCatalog.Services.CatalogService Catalog

<h1 class="mb-4">Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
            <strong>@selectedCourseTitle</strong> has been received. You will be notified by email once it is processed.</p>
        <a href="/courses" class="btn btn-primary mt-2">Browse More Courses</a>
    </div>
}
else
{
    <p class="text-muted">Fill out the form below to request enrollment in a course.</p>

    <form method="post" @formname="enrollment">
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" class="form-control" required />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control" required placeholder="e.g., STU-123456" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <select id="courseId" name="Model.CourseId" class="form-select" required>
                <option value="">— Select a course —</option>
                @foreach (var course in Catalog.GetAllCourses())
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.DepartmentCode @course.CourseNumber — @course.Title</option>
                }
            </select>
        </div>

        <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
        <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
    </form>
}

@code {
    [SupplyParameterFromForm]
    public CourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool submitted;
    private string selectedCourseTitle = "";

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        // Check if this is a POST (form was submitted)
        if (!string.IsNullOrWhiteSpace(Model.StudentName) && Model.CourseId > 0)
        {
            var course = Catalog.GetCourse(Model.CourseId);
            selectedCourseTitle = course is not null ? $"{course.DepartmentCode} {course.CourseNumber} — {course.Title}" : "Unknown";
            submitted = Catalog.SubmitEnrollmentRequest(Model);
        }
    }
}

